mapper.select:
SELECT resource_ref FROM audit_event WHERE project_id=#{projectId} AND subject_id=#{userId}
    AND action=#{action} AND result='SUCCESS' AND reason_code IS NULL
    AND request_id=#{requestId} AND trace_id=#{requestId} AND schema_version='1.0.0'
    AND schema_manifest_sha256=#{operationManifest} AND created_by=#{userId} AND classification=#{classification}
    AND resource_ref->>'$.decision_id'=#{decisionId} AND resource_ref->>'$.operation_id'=#{operationId}

SELECT payload FROM outbox_event WHERE aggregate_id=#{taskId} AND aggregate_revision=#{resultingRevision}
    AND event_type=#{action} AND payload->>'$.data.decision_id'=#{decisionId}
    AND payload->>'$.data.operation_id'=#{operationId}

SELECT created_at FROM operation_record WHERE operation_id=#{operationId} AND subject_id=#{userId}
    AND operation_name='TK-01-DRAFT' AND idempotency_key=#{key} AND target_id=#{projectId}
    AND state='COMPLETED' AND revision=2 AND error_code IS NULL AND http_status=201
    AND schema_version='1.0.0' AND schema_manifest_sha256=#{operationManifest}
    AND created_by=#{userId} AND classification=#{classification}

SELECT resource_ref FROM audit_event WHERE project_id=#{projectId} AND subject_id=#{userId}
    AND action='task.input_draft.saved' AND result='SUCCESS' AND reason_code IS NULL
    AND request_id=#{requestId} AND trace_id=#{requestId} AND schema_version='1.0.0'
    AND schema_manifest_sha256=#{operationManifest} AND created_by=#{userId} AND classification=#{classification}
    AND resource_ref->>'$.operation_id'=#{operationId}

mapper.update:
UPDATE operation_record SET state='COMPLETED',http_status=#{httpStatus},response_ref=CAST(#{response} AS JSON),
    revision=2,updated_at=#{now}
WHERE operation_id=#{operationId} AND subject_id=#{userId} AND operation_name=#{operationName}
    AND idempotency_key=#{key} AND request_sha256=#{requestHash} AND state='PROCESSING'
    AND revision=1 AND target_id=#{taskId} AND schema_manifest_sha256=#{operationManifest}

mapper.insert:
INSERT INTO task_input_revision(project_id,task_id,task_revision,operation_id,document_type,owner_id,goal,based_on_document_revision,
    request_json,request_sha256,scope_json,scope_sha256,missing_requirements,requirements_sha256,authority_grant,authority_revision,
    auth_epoch,governance_epoch,schema_version,schema_manifest_sha256,created_by,created_at,classification)
SELECT i.project_id,i.task_id,#{taskRevision},#{operationId},i.document_type,i.owner_id,i.goal,i.based_on_document_revision,
    i.request_json,i.request_sha256,i.scope_json,i.scope_sha256,i.missing_requirements,i.requirements_sha256,
    #{authorityGrant},#{authorityRevision},#{authEpoch},#{governanceEpoch},i.schema_version,i.schema_manifest_sha256,
    #{userId},#{now},i.classification
FROM task_input_revision i WHERE i.project_id=#{projectId} AND i.task_id=#{taskId} AND i.task_revision=#{basisTaskRevision}
    AND i.request_sha256=#{inputHash} AND i.scope_sha256=#{scopeHash} AND i.requirements_sha256=#{requirementsHash}
    AND i.schema_version='1.0.0' AND i.schema_manifest_sha256=#{manifest} AND i.classification=#{classification}

mapper.update:
UPDATE task_head SET current_revision=#{taskRevision}
WHERE project_id=#{projectId} AND task_id=#{taskId} AND current_revision IS NULL AND revision=1
    AND status=#{taskStatus} AND owner_id=#{ownerId} AND created_by=#{userId} AND created_at=#{now}

mapper.select:
SELECT resource_ref FROM audit_event WHERE project_id=#{projectId} AND subject_id=#{userId} AND action='task.created'
    AND result='SUCCESS' AND schema_version='1.0.0' AND schema_manifest_sha256=#{manifest}
    AND resource_ref->>'$.operation_id'=#{operationId} AND resource_ref->>'$.task_id'=#{taskId}

mapper.update:
UPDATE task_revision SET plan_revision=#{planRevision}
WHERE project_id=#{projectId} AND task_id=#{taskId} AND task_revision=#{taskRevision} AND parent_revision=#{basisTaskRevision}
    AND plan_revision IS NULL AND content_sha256=#{taskRevisionHash} AND created_by=#{userId} AND created_at=#{now}

UPDATE task_head SET current_revision=#{taskRevision},status=#{taskStatus},revision=#{resultingRevision},updated_at=#{now}
WHERE project_id=#{projectId} AND task_id=#{taskId} AND current_revision=#{basisTaskRevision}
    AND status=#{fromStatus} AND revision=#{expectedRevision}

UPDATE plan_revision SET decision_id=#{decisionId}
WHERE project_id=#{projectId} AND task_id=#{taskId} AND task_revision=#{taskRevision} AND plan_revision=#{planRevision}
    AND content_sha256=#{contentHash} AND status='CONFIRMED' AND decision_id IS NULL AND created_by=#{userId} AND created_at=#{now}

