    AND action=#{action} AND result='SUCCESS' AND reason_code IS NULL AND request_id=#{requestId} AND trace_id=#{requestId}
    AND schema_version='1.0.0' AND schema_manifest_sha256=#{operationManifest} AND created_by=#{userId} AND classification=#{classification}
